CREATE TABLE "ad_purchases" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"vendor_id" uuid NOT NULL,
	"ad_product_id" uuid NOT NULL,
	"billing_model" "ad_billing_model" NOT NULL,
	"price_npr" numeric(12, 2) NOT NULL,
	"budget_npr" numeric(12, 2),
	"settlement_model" "settlement_model" NOT NULL,
	"status" "ad_purchase_status" DEFAULT 'ACTIVE' NOT NULL,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"amount_paid_npr" numeric(12, 2) DEFAULT 0 NOT NULL,
	"agreed_by_user_id" uuid NOT NULL,
	"agreed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"idempotency_key" text NOT NULL,
	CONSTRAINT "ad_purchases_price_check" CHECK ("ad_purchases"."price_npr" > 0),
	CONSTRAINT "ad_purchases_budget_check" CHECK (("ad_purchases"."billing_model" = 'PER_ORDER_PREMIUM') = ("ad_purchases"."budget_npr" IS NOT NULL) AND ("ad_purchases"."budget_npr" IS NULL OR "ad_purchases"."budget_npr" >= "ad_purchases"."price_npr")),
	CONSTRAINT "ad_purchases_dates_check" CHECK ("ad_purchases"."ends_at" > "ad_purchases"."starts_at"),
	CONSTRAINT "ad_purchases_amount_paid_check" CHECK ("ad_purchases"."amount_paid_npr" >= 0),
	CONSTRAINT "ad_purchases_idempotency_key_check" CHECK (char_length("ad_purchases"."idempotency_key") BETWEEN 8 AND 100)
);
--> statement-breakpoint
CREATE TABLE "settlement_model_change_requests" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"vendor_id" uuid NOT NULL,
