	CONSTRAINT "settlement_model_change_requests_decision_check" CHECK (("settlement_model_change_requests"."status" = 'PENDING') = ("settlement_model_change_requests"."decided_at" IS NULL) AND ("settlement_model_change_requests"."decided_at" IS NULL) = ("settlement_model_change_requests"."decided_by_user_id" IS NULL)),
	CONSTRAINT "settlement_model_change_requests_reason_check" CHECK ("settlement_model_change_requests"."rejection_reason" IS NULL OR ("settlement_model_change_requests"."status" = 'REJECTED' AND btrim("settlement_model_change_requests"."rejection_reason") <> ''))
);
