-- Only the shop's own account files a model change request: an admin decides one, never makes one.
CREATE FUNCTION guard_settlement_model_change_request() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM vendors v WHERE v.id = NEW.vendor_id AND v.user_id = NEW.requested_by_user_id
  ) THEN
    RAISE EXCEPTION 'a settlement model change is requested by the vendor''s own account'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER settlement_model_change_requests_guard BEFORE INSERT ON settlement_model_change_requests
  FOR EACH ROW EXECUTE FUNCTION guard_settlement_model_change_request();
--> statement-breakpoint
-- No unilateral billing (SPEC core 8): an ad purchase exists only by the vendor's own agreement,
-- and who bought what, for which shop, at what terms never changes afterwards.
CREATE FUNCTION guard_ad_purchase() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM vendors v WHERE v.id = NEW.vendor_id AND v.user_id = NEW.agreed_by_user_id
    ) THEN
      RAISE EXCEPTION 'an ad is bought by the vendor''s own account'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF (NEW.vendor_id, NEW.ad_product_id, NEW.billing_model, NEW.price_npr, NEW.settlement_model,
      NEW.agreed_by_user_id, NEW.agreed_at, NEW.idempotency_key)
     IS DISTINCT FROM
     (OLD.vendor_id, OLD.ad_product_id, OLD.billing_model, OLD.price_npr, OLD.settlement_model,
      OLD.agreed_by_user_id, OLD.agreed_at, OLD.idempotency_key) THEN
    RAISE EXCEPTION 'the terms a vendor agreed to for an ad purchase never change'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER ad_purchases_guard BEFORE INSERT OR UPDATE ON ad_purchases
  FOR EACH ROW EXECUTE FUNCTION guard_ad_purchase();
